from collections import deque, defaultdict
import heapq

class Graph:
    def __init__(self):
        self._nodes = set()
        self._adjacency_list = defaultdict(list)
        self._edge_weights = defaultdict(dict)

    def add_node(self, node):
        """
        Adds a node to the graph.
        """
        if node not in self._nodes:
            self._nodes.add(node)
            self._adjacency_list[node] = []
            self._edge_weights[node] = {}

    def add_edge(self, from_node, to_node, weight=1):
        """
        Adds an edge between two nodes with an optional weight.
        """
        if from_node not in self._nodes or to_node not in self._nodes:
            raise ValueError("Both nodes must exist in the graph.")

        if to_node in self._adjacency_list[from_node]:
            raise ValueError("Edge already exists between the nodes.")

        self._adjacency_list[from_node].append(to_node)
        self._edge_weights[from_node][to_node] = weight

    def shortest_path(self, start, end):
        """
        Computes the shortest path from start to end using Dijkstra's algorithm.
        Returns a tuple of (path, distance) or (None, None) if no path exists.
        """
        if start not in self._nodes or end not in self._nodes:
            return (None, None)

        # Priority queue: (distance, current_node, path)
        priority_queue = [(0, start, [start])]
        visited = set()

        while priority_queue:
            dist, current, path = heapq.heappop(priority_queue)

            if current == end:
                return (path, dist)

            if current in visited:
                continue

            visited.add(current)

            for neighbor in self._adjacency_list[current]:
                new_dist = dist + self._edge_weights[current][neighbor]
                new_path = path + [neighbor]

                heapq.heappush(priority_queue, (new_dist, neighbor, new_path))

        return (None, None)
```

